public void initReconExecPlan(){
        //1.获取可用的对账规则
        List<ReconRuleConfigDo> reconRuleConfigDoList = reconRuleConfigDoTunnel.queryInitTaskAndAvailableReconRules();
        if (CollectionUtils.isEmpty(reconRuleConfigDoList)) {
            return;
        }
        reconRuleConfigDoList.forEach(reconRuleConfigDo -> {
            try {
                initReconExecPlan(reconRuleConfigDo);
            } catch (Exception e) {
                dingErrorMsgComponent.sendError("初始化对账任务异常", e);
                log.error("初始化对账任务异常！", e);
            }
        });
    }

@Transactional(rollbackFor = Exception.class)
    public void insertBatchReconExecPlan(List<ReconExecPlanDo> reconExecPlanDoList, String reconRuleId){
        if(CollectionUtils.isEmpty(reconExecPlanDoList)){
            return;
        }
        reconExecPlanDoTunnel.insertBatch(reconExecPlanDoList);
        reconRuleConfigDoTunnel.updateIsInitExecPlanByRuleId(reconRuleId, InitExecPlanEnum.READY_INIT.getCode());
    }

@Override
    public int updateIsInitExecPlanByRuleId(String reconRuleId, Integer isInitExecPlan) {
        return reconRuleConfigDoMapper.updateIsInitExecPlanByRuleId(reconRuleId, isInitExecPlan);
    }
